let djP2={};try{djP2=JSON.parse(localStorage.getItem(DJ_P2_KEY)||'{}')||{}}catch(e){djP2={}}
function djCourseOrdinal(value){
 const raw=String(value??'').trim();
 if(!raw)return '';
 const normalized=raw.replace(/(\d+)\.º/g,'$1º').replace(/(\d+)\.ª/g,'$1ª');
 // Compatibilidad con registros históricos de dos cifras: 13 = 1.º 3.ª.
 // No convertir valores de una cifra en divisiones inventadas.
 let m=raw.match(/^([1-9])([1-9])$/);
 if(m)return m[1]+'º '+m[2]+'ª';
 m=raw.match(/^(\d+)(?:\s*(?:º|°|ro|er|\.º))?\s*(?:año)?\s*[,\- /]+\s*(\d+)(?:\s*(?:ª|°|ra|\.ª))?$/i);
 if(m)return m[1]+'º '+m[2]+'ª';
 return normalized;
}
function djP2Change(key,value){
 if(key==='registro'||key==='antiguedad'||key==='clase')value=String(value).replace(/\D/g,'');
 djP2[key]=value;localStorage.setItem(DJ_P2_KEY,JSON.stringify({fecha:djP2.fecha||'',lugar:djP2.lugar||'',copiarFecha:djP2.copiarFecha===true}));
 const focus=document.activeElement;const k=focus?.dataset?.djp2;const pos=focus?.selectionStart;
 $('djPreview').innerHTML=djPreviewHTML({nombre:$('nombre').value,apellidos:$('perfilApellidos').value,nombres:$('perfilNombres').value,dni:$('dni').value,presentedAt:inst.find(i=>String(i.id)===djPresentedAt)?.name||'',page2:structuredClone(djPage2Current()),rows:djSnapshotRows()});
 if(k&&(key==='registro'||key==='antiguedad'||key==='clase')){focus.value=value;try{focus.setSelectionRange(Math.min(pos,value.length),Math.min(pos,value.length))}catch(e){}}
}
function djP2Date(p){const date=p.fecha||'';if(!/^\d{4}-\d{2}-\d{2}$/.test(date))return null;const [y,m,d]=date.split('-').map(Number);if(m<1||m>12||d<1||d>31)return null;return {dia:String(d),mes:['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'][m-1],anio:String(y)};}
// v0.9.16.10: datos personales/profesionales salen exclusivamente de Mi perfil.
function djPerfilPage2(){adcActualizarAntiguedad(false);
 const campos={clase:'perfilClase',domicilio:'perfilDomicilio',localidad:'perfilLocalidad',titulo:'perfilTitulo',otorgado:'perfilOtorgado',registro:'perfilRegistro',antiguedad:'perfilAntiguedad'};
 const p={};for(const [k,id] of Object.entries(campos))p[k]=($(id)?.value||'').trim();
 const sex=$('sexo')?.value||'';
 p.sexo=sex==='M'?'Masculino':sex==='F'?'Femenino':sex==='O'?'Otro':'';
 return p;
}
function djPage2Current(){return {...djP2,...djPerfilPage2()};}
